<body>
  <div id="controls">
    <button id="mat-sand">Sand</button>
    <button id="mat-water">Water</button>
    <button id="mat-wall">Wall</button>
    <button id="mat-acid">Acid</button>
    <button id="mat-empty">Erase</button>
    <button id="clear">Clear</button>
  </div>
  <canvas id="sand" width="400" height="400"></canvas>

  <script>
    const canvas = document.getElementById('sand');
    const ctx = canvas.getContext('2d');
    const cellSize = 5;
    const w = 80;
    const h = 80;

    let grid = Array.from({ length: h }, () => Array(w).fill('empty'));
    let selectedMaterial = 'sand';

    document.getElementById('clear').onclick = () => {
      window.sim.clear();
    };

    document.querySelectorAll('#controls button').forEach(btn => {
      btn.onmousedown = (e) => {
        if (btn.id.startsWith('mat-')) {
          const mat = btn.id.split('-')[1];
          selectedMaterial = mat;
        }
      };
    });

    let isPainting = false;
    canvas.onmousedown = () => {
      isPainting = true;
    };
    canvas.onmouseup = canvas.onmouseleave = () => {
      isPainting = false;
    };

    const colorMap = {
      'sand': '#FFD700',
      'water': '#1E90FF',
      'wall': '#808080',
      'acid': '#32CD32',
      'empty': ''
    };

    function drawCanvas() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const mat = grid[y][x];
          if (mat === 'empty') continue;
          ctx.fillStyle = colorMap[mat];
          ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
        }
      }
    }

    function deepCopyGrid(g) {
      return g.map(row => [...row]);
    }

    window.sim = {
      w,
      h,
      tick(n) {
        for (let step = 0; step < n; step++) {
          let newGrid = deepCopyGrid(grid);
          for (let y = h - 1; y >= 0; y--) {
            for (let x = 0; x < w; x++) {
              const mat = grid[y][x];
              if (mat === 'empty' || mat === 'wall') continue;
              switch(mat) {
                case 'sand':
                  processSand(x, y, newGrid);
                  break;
                case 'water':
                  processWater(x, y, newGrid);
                  break;
                case 'acid':
                  processAcid(x, y, newGrid);
                  break;
              }
            }
          }
          grid = newGrid;
        }
      },
      get(x, y) {
        if (x < 0 || x >= w || y < 0 || y >= h) return 'empty';
        return grid[y][x];
      },
      set(x, y, material) {
        if (x < 0 || x >= w || y < 0 || y >= h) return;
        grid[y][x] = material;
        drawCanvas();
      },
      clear() {
        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            grid[y][x] = 'empty';
          }
        }
        drawCanvas();
      }
    };

    function processSand(x, y, newGrid) {
      const belowY = y + 1;
      if (belowY < h) {
        const belowMat = grid[belowY][x];
        if (['empty', 'water', 'acid'].includes(belowMat)) {
          newGrid[y][x] = 'empty';
          newGrid[belowY][x] = 'sand';
          return;
        }
      }

      const dirs = x % 2 === 0 ? [-1, 1] : [1, -1];
      for (let dx of dirs) {
        const nx = x + dx;
        if (nx < 0 || nx >= w) continue;
        const diagY = y + 1;
        if (diagY < h) {
          const diagMat = grid[diagY][nx];
          if (['empty', 'water', 'acid'].includes(diagMat)) {
            newGrid[y][x] = 'empty';
            newGrid[diagY][nx] = 'sand';
            return;
          }
        }
      }
    }

    function processWater(x, y, newGrid) {
      const belowY = y + 1;
      if (belowY < h) {
        const belowMat = grid[belowY][x];
        if (['empty', 'acid'].includes(belowMat)) {
          newGrid[y][x] = 'empty';
          newGrid[belowY][x] = 'water';
          return;
        }
      }

      const dirs = [-1, 1]; // left first
      for (let dx of dirs) {
        const nx = x + dx;
        if (nx < 0 || nx >= w) continue;
        const sameMat = grid[y][nx];
        if (sameMat === 'empty') {
          newGrid[y][x] = 'empty';
          newGrid[y][nx] = 'water';
          return;
        }
      }
    }

    function processAcid(x, y, newGrid) {
      let moved = false;
      let newX = x, newY = y;

      const belowY = y + 1;
      if (belowY < h) {
        const belowMat = grid[belowY][x];
        if (['empty', 'acid'].includes(belowMat)) {
          newGrid[y][x] = 'empty';
          newGrid[belowY][x] = 'acid';
          newX = x;
          newY = belowY;
          moved = true;
        }
      }

      if (!moved) {
        const dirs = [-1, 1];
        for (let dx of dirs) {
          const nx = x + dx;
          if (nx < 0 || nx >= w) continue;
          const sameMat = grid[y][nx];
          if (sameMat === 'empty') {
            newGrid[y][x] = 'empty';
            newGrid[y][nx] = 'acid';
            newX = nx;
            newY = y;
            moved = true;
            break;
          }
        }
      }

      const dissolveDirs = [
        { dx: 0, dy: +1 },
        { dx: -1, dy: 0 },
        { dx: +1, dy: 0 }
      ];

      for (let dir of dissolveDirs) {
        const nx = moved ? newX + dir.dx : x + dir.dx;
        const ny = moved ? newY + dir.dy : y + dir.dy;
        if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
        const targetMat = grid[ny][nx];
        if (targetMat === 'sand' || targetMat === 'wall') {
          newGrid[ny][nx] = 'empty';
        }
      }
    }

    canvas.onmousemove = function(e) {
      if (!isPainting) return;
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;
      const gridX = Math.floor(mouseX / cellSize);
      const gridY = Math.floor(mouseY / cellSize);
      window.sim.set(gridX, gridY, selectedMaterial);
    };

    drawCanvas();
  </script>
